function validate([routes, source, target]) {
  if (!Array.isArray(routes) || routes.length < 1 || routes.length > 500) return 'routes needs 1 to 500 buses.';
  let total = 0;
  for (const route of routes) {
    if (!Array.isArray(route) || route.length < 1) return 'Every route needs at least one stop.';
    total += route.length;
    if (total > 100000) return 'All routes together hold at most 10^5 stops.';
    if (route.some((stop) => !Number.isInteger(stop) || stop < 0 || stop >= 1000000)) return 'Stops are whole numbers from 0 to 999999.';
    if (new Set(route).size !== route.length) return 'A route cannot list the same stop twice.';
  }
  for (const stop of [source, target]) {
    if (!Number.isInteger(stop) || stop < 0 || stop >= 1000000) return 'source and target are whole numbers from 0 to 999999.';
  }
  return null;
}

