function numBusesToDestination(routes, source, target) {
  if (source === target) return 0;
  const busesAt = new Map();
  for (let bus = 0; bus < routes.length; bus++) {
    for (const stop of routes[bus]) {
      if (!busesAt.has(stop)) busesAt.set(stop, []);
      busesAt.get(stop).push(bus);
    }
  }
  if (!busesAt.has(source) || !busesAt.has(target)) return -1;

  const usedBus = new Array(routes.length).fill(false);
  const seenStop = new Set([source]);
  let queue = [source];
  let buses = 0;
  while (queue.length > 0) {
    buses++;
    const next = [];
    for (const stop of queue) {
      for (const bus of busesAt.get(stop)) {
        if (usedBus[bus]) continue;
        usedBus[bus] = true;
        for (const nextStop of routes[bus]) {
          if (nextStop === target) return buses;
          if (seenStop.has(nextStop)) continue;
          seenStop.add(nextStop);
          next.push(nextStop);
        }
      }
    }
    queue = next;
  }
  return -1;
}

