function numBusesToDestination(routes, source, target) {
  // Relax "fewest boardings to be on bus i" over every pair of buses that share a stop, until nothing changes.
  if (source === target) return 0;
  const k = routes.length;
  const sets = routes.map((route) => new Set(route));
  const shares = sets.map((_, i) => sets.map((other, j) => i !== j && routes[i].some((stop) => other.has(stop))));
  const dist = sets.map((set) => (set.has(source) ? 1 : Infinity));
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < k; i++) {
      if (dist[i] === Infinity) continue;
      for (let j = 0; j < k; j++) {
        if (shares[i][j] && dist[i] + 1 < dist[j]) {
          dist[j] = dist[i] + 1;
          changed = true;
        }
      }
    }
  }
  let best = Infinity;
  for (let i = 0; i < k; i++) {
    if (sets[i].has(target)) best = Math.min(best, dist[i]);
  }
  return best === Infinity ? -1 : best;
}

