function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  if (size === 'small') {
    const count = 1 + pick(5);
    const routes = [];
    for (let i = 0; i < count; i++) {
      const length = 1 + pick(4);
      const stops = new Set();
      while (stops.size < length) stops.add(pick(10));
      routes.push([...stops]);
    }
    return [routes, pick(11), pick(11)];
  }
  // Large: stops are spread along a line and each bus serves a stretch of it, so trips need many buses.
  const ids = new Set();
  while (ids.size < 1500) ids.add(pick(1000000));
  const line = [...ids];
  const count = 200 + pick(301);
  const width = 10 + pick(60);
  const routes = [];
  let total = 0;
  for (let i = 0; i < count && total < 18000; i++) {
    const center = pick(line.length);
    const length = 1 + pick(40);
    const stops = new Set();
    for (let tries = 0; stops.size < length && tries < 200; tries++) {
      const at = center - width + pick(2 * width + 1);
      if (at >= 0 && at < line.length) stops.add(line[at]);
    }
    if (stops.size === 0) stops.add(line[center]);
    routes.push([...stops]);
    total += stops.size;
  }
  const source = rand() < 0.95 ? line[pick(line.length)] : pick(1000000);
  const target = rand() < 0.95 ? line[pick(line.length)] : pick(1000000);
  return [routes, source, target];
}
